rollback.sql:
DO $guard$ BEGIN
 IF EXISTS(SELECT 1 FROM "${schema}".organization_membership_installation)
 OR EXISTS(SELECT 1 FROM "${schema}".organization_membership_lifecycle_receipt)
 OR EXISTS(SELECT 1 FROM "${schema}".organization_fact_bootstrap WHERE status IN ('PAUSED','STOPPED'))
 THEN RAISE EXCEPTION 'Membership lifecycle ownership/receipts exist; rollback requires reviewed reconciliation, never deletion'; END IF;
END $guard$;
CREATE OR REPLACE FUNCTION "${schema}".organization_membership_active(company uuid,org uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $active$
 SELECT EXISTS(SELECT 1 FROM "${schema}".organization_fact_bootstrap b WHERE b.tenant_id=company AND b.organization_id=org AND b.status IN ('PENDING','COMPLETE'))
$active$;
CREATE OR REPLACE FUNCTION "${schema}".organization_reporting_owned(company uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $owned$
 SELECT EXISTS(SELECT 1 FROM "${schema}".organization_fact_bootstrap b WHERE b.tenant_id=company AND b.status IN ('PENDING','COMPLETE'))
$owned$;
CREATE OR REPLACE FUNCTION "${schema}".organization_reporting_retirement_allowed(company uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $retire$ SELECT false $retire$;
ALTER TABLE "${schema}".organization_fact_bootstrap DROP CONSTRAINT organization_fact_bootstrap_status_check;
ALTER TABLE "${schema}".organization_fact_bootstrap ADD CONSTRAINT organization_fact_bootstrap_status_check CHECK(status IN ('PENDING','COMPLETE'));
ALTER TABLE "${schema}".organization_grant_installation DROP COLUMN status;
DROP TABLE "${schema}".organization_membership_lifecycle_receipt;
DROP TABLE "${schema}".organization_membership_installation;
